mapper.select:
SELECT FROM ich_post WHERE is_deleted = 0 AND status = 1
AND (title LIKE CONCAT('%', #{keyword}, '%') OR tags LIKE CONCAT('%', #{keyword}, '%'))
AND type = #{type}
ORDER BY CASE WHEN create_time > DATE_SUB(NOW(), INTERVAL 5 MINUTE) THEN 0 ELSE 1 END ASC, CASE WHEN create_time > DATE_SUB(NOW(), INTERVAL 5 MINUTE) THEN create_time END DESC, (like_count + comment_count * 2 + favorite_count * 1.5) / POW(TIMESTAMPDIFF(HOUR, create_time, NOW()) + 2, 0.8) DESC, create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM ich_post WHERE is_deleted = 0 AND status = 1
AND (title LIKE CONCAT('%', #{keyword}, '%') OR tags LIKE CONCAT('%', #{keyword}, '%'))
AND type = #{type}
